"use strict";(self.webpackChunknotes=self.webpackChunknotes||[]).push([["791"],{9533(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>c,frontMatter:()=>s,contentTitle:()=>a,toc:()=>l,assets:()=>m});var i=JSON.parse('{"id":"DSA/DynamicProgramming/Form2/index","title":"Form 2","description":"When the dp subproblem gets reduced to finding a solution for dp[0...i], to be able to solve for dp[0...n] it can be solved with form 2. Note that dp[0...i] might not be the answer to the problem but might be something that\'ll be needed to arrive at the final answer. Now it\'s not to say that it can\'t be solved with any other form, but it\'s easier to solve it considering the subproblems definition to be from [0...i].","source":"@site/docs/DSA/DynamicProgramming/Form2/index.md","sourceDirName":"DSA/DynamicProgramming/Form2","slug":"/DSA/DynamicProgramming/Form2/","permalink":"/Notes/DSA/DynamicProgramming/Form2/","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Form 2"},"sidebar":"dsaSidebar","previous":{"title":"Iterative Techniques","permalink":"/Notes/DSA/DynamicProgramming/Form1/problem1"},"next":{"title":"Form 3","permalink":"/Notes/DSA/DynamicProgramming/Form3/"}}'),o=t(4848),r=t(8453);let s={title:"Form 2"},a,m={},l=[];function d(e){let n={br:"br",code:"code",p:"p",pre:"pre",strong:"strong",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(n.p,{children:["When the dp subproblem gets reduced to finding a solution for ",(0,o.jsx)(n.code,{children:"dp[0...i]"}),", to be able to solve for ",(0,o.jsx)(n.code,{children:"dp[0...n]"})," it can be solved with form 2. Note that ",(0,o.jsx)(n.code,{children:"dp[0...i]"})," might not be the answer to the problem but might be something that'll be needed to arrive at the final answer. Now it's not to say that it can't be solved with any other form, but it's easier to solve it considering the subproblems definition to be from ",(0,o.jsx)(n.code,{children:"[0...i]"}),".",(0,o.jsx)(n.br,{}),"\n","Generally speaking array problems can either be solved with Form 1 (Knapsack), Form 2 (ending at i) or Form 4 (LRDP). Like in Form 1, the states are made using the constraints and the nodal state ",(0,o.jsx)(n.code,{children:"i"})," itself. Consider the following problem:"]}),"\n",(0,o.jsxs)(n.p,{children:["Given an array of size N, and a positive integer K, maximize the sum of minimums of the K partitions. Given ",(0,o.jsx)(n.code,{children:"N, K <= 1e3"}),"."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Solution:"}),(0,o.jsx)(n.br,{}),"\n","Let ",(0,o.jsx)(n.code,{children:"DP(i, X)"})," denote the maximum sum of minimums of X partitions. The transition tries to find the first element of the last partition. We can say ",(0,o.jsx)(n.code,{children:"DP(i, X) = max(min(j...i) + DP(j-1, X-1))"})," where j can be anything in ",(0,o.jsx)(n.code,{children:"[0...i]"}),". If we can figure out a way to optimally do this, our final answer will simply be ",(0,o.jsx)(n.code,{children:"DP(N-1, K)"}),".",(0,o.jsx)(n.br,{}),"\n","Note that ",(0,o.jsx)(n.code,{children:"i == -1"})," is the base case rather than ",(0,o.jsx)(n.code,{children:"i == 0"})," because a partition can start at index 0, meaning the last valid subproblem consumes all elements down to index 0, leaving ",(0,o.jsx)(n.code,{children:"i = -1"})," with ",(0,o.jsx)(n.code,{children:"x = 0"})," remaining partitions.",(0,o.jsx)(n.br,{}),"\n","TC check: ",(0,o.jsx)(n.code,{children:"O(N\xb2 * K)"})," \u2014 N*K states, each with an O(N) transition loop."]}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-cpp",children:"const int inf = 1e9;\nint n = v.size(); // let v be the input array\nint dp[1010][1010];\nmemset(dp, -1, sizeof(dp));\n\nint rec(int i, int x){\n    if(x == 0 && i >= 0) return -inf;\n    /***\n    You have elements remaining but your partitions are done, so you never know\n    if you're missing out on better contributing elements. Such a case is invalid.\n    ***/\n    if(i == -1){\n        if(x == 0) return 0;\n        return -inf;\n    }\n\n    if(dp[i][x] != -1) return dp[i][x];\n\n    int ans = -inf;\n    int m = inf;\n    for(int j = i; j >= 0; j--){\n        m = min(m, v[j]);\n        ans = max(ans, m + rec(j-1, x-1));\n    }\n    /***\n    We iterate over all starting positions j of the xth partition,\n    tracking the running minimum from i down to j.\n    ans = max of (min in xth partition + optimal solution for x-1 partitions over [0...j-1]).\n    ***/\n\n    return dp[i][x] = ans;\n}\n"})})]})}function c(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>a});var i=t(6540);let o={},r=i.createContext(o);function s(e){let n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);